g=[[1]*29 for _ in range(20)]
# rectangle outline and interior fill
for r0,r1,c0,c1,color in [(0,3,4,7,5),(6,12,13,19,4),(14,16,10,12,5)]:
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if r in (r0,r1) or c in (c0,c1): g[r][c]=color
            else: g[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in g))

g=[[1]*29 for _ in range(20)]
for r0,r1,c0,c1,color in [(0,3,4,7,5),(6,12,13,19,4),(14,16,10,12,5)]:
    n=r1-r0-1
    fill=2 if n%2==0 else 7
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if r in (r0,r1) or c in (c0,c1): g[r][c]=color
            else: g[r][c]=fill
import json
print(json.dumps(g,separators=(',',':')))
